<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { consultarConsistencias, obtenerMesesConsistencias, obtenerOpcionesConsistencias } from '../services/consistencias'
import type { ConsistenciasData, ConsistenciasFiltros, MesConsistencia } from '../interfaces/consistencias.interface'
const filtros=reactive<ConsistenciasFiltros>({anio:null,mes_inicio:null,mes_fin:null}),anios=ref<number[]>([]),meses=ref<MesConsistencia[]>([]),data=ref<ConsistenciasData|null>(null),loading=ref(false),consultado=ref(false),error=ref('')
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la consulta.'
const money=(v:number)=>new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0))
const cuadrado=computed(()=>data.value?Math.abs(data.value.totalGeneralDebe-data.value.totalGeneralHaber)<.01:false)
async function load(){loading.value=true;try{const r=await obtenerOpcionesConsistencias();anios.value=r.anios;meses.value=r.meses??[];data.value=r.data}catch(v){error.value=message(v)}finally{loading.value=false}}
async function changeYear(){filtros.mes_inicio=null;filtros.mes_fin=null;meses.value=filtros.anio?await obtenerMesesConsistencias(filtros.anio):[]}
async function search(){if(!filtros.anio||!filtros.mes_inicio||!filtros.mes_fin)return void(error.value='Seleccione el año y el rango de meses.');if(filtros.mes_inicio>filtros.mes_fin)return void(error.value='El mes inicial no puede ser mayor que el mes final.');loading.value=true;consultado.value=true;error.value='';try{const r=await consultarConsistencias(filtros);data.value=r.data}catch(v){error.value=message(v)}finally{loading.value=false}}
function clear(){Object.assign(filtros,{anio:null,mes_inicio:null,mes_fin:null});meses.value=[];data.value=null;consultado.value=false;error.value=''}
onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad/proceso-contable">Proceso contable</RouterLink> / Consistencias</nav><header class="hero"><div class="mark">CO</div><div><small>MIA · CONTABILIDAD · PROCESO</small><h1>Consistencias contables</h1><p>Valida la cuadratura Debe/Haber de los comprobantes registrados en el periodo.</p></div></header><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="search"><label>Año *<select v-model="filtros.anio" @change="changeYear"><option :value="null">Seleccione</option><option v-for="a in anios" :key="a" :value="a">{{a}}</option></select></label><label>Mes inicial *<select v-model="filtros.mes_inicio"><option :value="null">Seleccione</option><option v-for="m in meses" :key="m.mes" :value="m.mes">{{m.mes_label}}</option></select></label><label>Mes final *<select v-model="filtros.mes_fin"><option :value="null">Seleccione</option><option v-for="m in meses" :key="m.mes" :value="m.mes">{{m.mes_label}}</option></select></label><footer><button type="button" class="soft" @click="clear">Limpiar</button><button :disabled="loading">{{loading?'Validando…':'Consultar'}}</button></footer></form><div v-if="loading" class="empty">Validando consistencias…</div><div v-else-if="consultado&&!data" class="empty">No se encontraron comprobantes para el periodo.</div><div v-else-if="!consultado" class="empty">Seleccione el periodo que desea validar.</div><main v-else-if="data"><aside :class="cuadrado?'status good':'status warning'"><b>{{cuadrado?'Contabilidad cuadrada':'Se encontraron diferencias'}}</b><span>Diferencia: S/ {{money(data.totalGeneralDebe-data.totalGeneralHaber)}}</span></aside><section v-for="tipo in data.dataPorTipo" :key="tipo.tipo_codigo" class="type"><header>{{tipo.tipo_codigo}} - {{tipo.tipo_nombre}}</header><article v-for="comp in tipo.comprobantes" :key="comp.id??`${comp.numero}-${comp.fecha}`"><h2>N.° {{comp.numero}} · {{comp.fecha}} · {{comp.glosa}}</h2><p>{{comp.origen}} · Documento: {{comp.fecha_doc||'—'}}</p><div class="scroll"><table><thead><tr><th>Cuenta</th><th>Nombre de la cuenta</th><th>Debe S/</th><th>Haber S/</th></tr></thead><tbody><tr v-for="det in comp.detalles" :key="`${comp.numero}-${det.cta_contable}`"><td><b>{{det.cta_contable}}</b></td><td>{{det.descripcion_cuenta}}</td><td class="num">{{money(det.debe)}}</td><td class="num">{{money(det.haber)}}</td></tr><tr v-if="!comp.detalles.length"><td colspan="4">Sin detalle</td></tr></tbody><tfoot><tr><th colspan="2">Total comprobante #{{comp.numero}}</th><td class="num">{{money(comp.total_debe)}}</td><td class="num">{{money(comp.total_haber)}}</td></tr></tfoot></table></div></article></section><footer class="grand"><b>Total general</b><span>S/ {{money(data.totalGeneralDebe)}}</span><span>S/ {{money(data.totalGeneralHaber)}}</span></footer></main></div></template>
<style scoped>
