lor:#fff;background:#334b58;text-align:right;font:700 .58rem monospace}.grand b{text-align:left}@media(max-width:620px){.filters{grid-template-columns:1fr}.status{display:grid;gap:5px}.grand{grid-template-columns:1fr}}
